#!/bin/sh
set -eu

crate_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
repo_dir=$(CDPATH= cd -- "$crate_dir/../.." && pwd)
formal_dir="$repo_dir/formal/dclutch-semantics"
accepted="$crate_dir/src/generated_admission_v3.rs"
temporary=$(mktemp "${TMPDIR:-/tmp}/dclutch-product-graded-admission-v3.XXXXXX")
trap 'rm -f "$temporary"' EXIT HUP INT TERM

(
  cd "$formal_dir"
  lake build DClutchSemantics.ProductGradedBasisAdmissionV3Abi
  lake env lean --run EmitProductGradedBasisAdmissionV3AbiRust.lean > "$temporary"
)

test "$(sed -n '1p' "$temporary")" = \
  '// @generated by EmitProductGradedBasisAdmissionV3AbiRust.lean; do not edit.'
grep -q '^pub const APPROXIMATION_CERTIFICATE_BYTES_V3: usize = 256;$' "$temporary"
grep -q '^pub const GRADED_BASIS_ADMISSION_BYTES_V3: usize = 304;$' "$temporary"
rustfmt --edition 2024 "$temporary"
cmp "$temporary" "$accepted"
